# Medido el 2026-09-21 en el cuaderno de llamadas: DeepSeek tarda 4 a 11 s, Big Pickle hasta 328 s
# y con A-47 se le espera hasta 600 s, el guardia corre la bateria en 262 s, y una tarea puede dar
# 4 vueltas de revision: 4 por (11 + 600) + 262 = 2706 s, y el tope de fuera tiene que ser mayor
# que la suma de los de dentro; SIN_AVANCE tiene que ser MAYOR que la llamada callada mas larga,
# la espera de Big Pickle de hasta 600 s, o se cortaria a una IA que esta contestando.
LIMITE_TAREA_SEGUNDOS = 420
SIN_AVANCE_SEGUNDOS = 660
TOPE_DURO_SEGUNDOS = 3000


def lanzar_al_equipo(proyecto, orden, tope_segundos=900):
    raiz = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    comando = [
        sys.executable,
        "ingeniero.py",
        "equipo",
        proyecto,
        orden["encargo"],
        "--escribe",
        "deepseek",
        "--revisa",
        "bigpickle",
    ]
    if orden.get("crear"):
        comando.append("--crear")
    entorno = dict(os.environ)
    entorno["PYTHONIOENCODING"] = "utf-8"
    entorno["INGENIERO_ETIQUETA"] = str(orden.get("id", ""))
    archivo = open(os.path.join(raiz, 'memoria', '.salida_tarea_' + str(orden.get('id', '')) + '.txt'), 'w', encoding='utf-8', errors='replace')
    proceso = subprocess.Popen(
        comando,
        cwd=raiz,
        stdout=archivo,
        stderr=subprocess.STDOUT,
        env=entorno,
    )

    def avance():
        total = 0.0
        try:
            import psutil
            pp = psutil.Process(proceso.pid)
            total += pp.cpu_times().user + pp.cpu_times().system
            for hijo in pp.children(recursive=True):
                try:
                    total += hijo.cpu_times().user + hijo.cpu_times().system
                except psutil.Error:
                    pass
            total = round(total, 1)
        except Exception:
            pass
        try:
            total += os.path.getsize(archivo.name)
        except Exception:
            pass
        for nombre in ('CUADERNO_DE_LLAMADAS.jsonl', 'APLICACIONES.log'):
            try:
                total += os.path.getmtime(os.path.join(raiz, 'memoria', nombre))
            except Exception:
                pass
        return total

    from cuerpo import vigilante
    estado = vigilante.esperar(proceso, LIMITE_TAREA_SEGUNDOS, SIN_AVANCE_SEGUNDOS, TOPE_DURO_SEGUNDOS, avance)
    archivo.close()
    with open(archivo.name, encoding='utf-8', errors='replace') as f:
        salida = f.read()
    if estado != 'termino':
        return {
            'guardado': False,
            'codigo': None,
            'salida': 'COLGADA: ' + estado + ' (sin avance pasado el limite; se busca la causa raiz)\n' + salida,
        }
    return {
        'guardado': 'GUARDADO AL MOMENTO' in salida,
        'codigo': proceso.returncode,
        'salida': salida,
    }


def tipo_de_fallo(salida):
    """Devuelve de que tipo fue el fallo, mirando el texto de salida."""
    if not isinstance(salida, str):
        return "otro"
    if salida.startswith("COLGADA:"):
        return "colgada"
    if salida.startswith("TOPE DE TIEMPO"):
        return "tiempo"
    if "EL GUARDIA NO DEJO GUARDAR" in salida or "NO SE GUARDO" in salida:
        return "guardia"
    if "EL EQUIPO NO APROBO" in salida:
        return "no_aprobo"
    if "no se pudo aplicar" in salida:
        return "no_aplico"
    return "otro"
